namespace EntMap.Constants
{
    public static class MapperSourceGeneratorConstants
    {
        public static string ClassName { get; set; } = "EntMapper";

        public static string GetInfrastructureSource(string namespaceName) => $$"""
            // <auto-generated />
                    #nullable enable
                    using System;
                    using System.Linq;

                    namespace {{namespaceName}}
                    {
                        internal static partial class {{ClassName}}
                        {
                            private static readonly System.Collections.Generic.Dictionary<(System.Type, System.Type), System.Delegate> _mappers = new();

                            static {{ClassName}}()
                            {
                                InitMappers();
                            }

                            static partial void InitMappers();

                            public static TTarget Map<TTarget>(object source)
                            {
                                if (source == null) return default!;
                        
                                var sourceType = source.GetType();
                                var targetType = typeof(TTarget);
                                var key = (sourceType, targetType);
                        
                                if (_mappers.TryGetValue(key, out var del))
                                {
                                    return ((System.Func<object, TTarget>)del)(source);
                                }

                                if (source is System.Collections.IEnumerable enumerable && targetType.IsGenericType)
                                {
                                    var targetItemType = targetType.GetGenericArguments().FirstOrDefault();
                                    if (targetItemType != null)
                                    {
                                        var listType = typeof(System.Collections.Generic.List<>).MakeGenericType(targetItemType);
                                        var list = (System.Collections.IList)System.Activator.CreateInstance(listType)!;
                                        foreach (var item in enumerable)
                                        {
                                            if (item == null) continue;
                                            var mapMethod = typeof({{ClassName}}).GetMethod("Map")!.MakeGenericMethod(targetItemType);
                                            list.Add(mapMethod.Invoke(null, new[] { item }));
                                        }
                                        return (TTarget)list;
                                    }
                                }

                                throw new System.InvalidOperationException($"Mapping from {sourceType.Name} to {targetType.Name} is not generated.");
                            }
                        }

                        //// Класс-профиль, аналогичный AutoMapper Profile
                        //public abstract class MappingProfile
                        //{
                        //    protected MemberConfigurationExpression<TSource, TTarget> CreateMap<TSource, TTarget>()
                        //    {
                        //        return new MemberConfigurationExpression<TSource, TTarget>();
                        //    }
                        //}
            
                        //// Инструмент для цепочки вызовов (Fluent API), который C# разрешает использовать как statement
                        //public interface IMappingExpression<TSource, TTarget>
                        //{
                        //    IMappingExpression<TSource, TTarget> ForMember<TValue>(
                        //        System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                        //        Func<TSource, TValue> mapFrom);
                        //}
            
                        //public class MemberConfigurationExpression<TSource, TTarget> : IMappingExpression<TSource, TTarget>
                        //{
                        //    public IMappingExpression<TSource, TTarget> ForMember<TValue>(
                        //        System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                        //        Func<TSource, TValue> mapFrom)
                        //    {
                        //        return this;
                        //    }
                        //} 
                    }

                    namespace {{namespaceName}}.Profile
                    {
                        // Класс-профиль, аналогичный AutoMapper Profile
                        public abstract class MappingProfile
                        {
                            protected MemberConfigurationExpression<TSource, TTarget> CreateMap<TSource, TTarget>()
                            {
                                return new MemberConfigurationExpression<TSource, TTarget>();
                            }
                        }
            
                        // Инструмент для цепочки вызовов (Fluent API), который C# разрешает использовать как statement
                        public interface IMappingExpression<TSource, TTarget>
                        {
                            IMappingExpression<TSource, TTarget> ForMember<TValue>(
                                System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                                Func<TSource, TValue> mapFrom);
                        }
            
                        public class MemberConfigurationExpression<TSource, TTarget> : IMappingExpression<TSource, TTarget>
                        {
                            public IMappingExpression<TSource, TTarget> ForMember<TValue>(
                                System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                                Func<TSource, TValue> mapFrom)
                            {
                                return this;
                            }
                        }   
                    }
            """;
    }
}
